import { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import BlogLayout from '../components/BlogLayout';
import ArticleBody from '../components/ArticleBody';
import ArticleCard from '../components/ArticleCard';
import ArticleDownloadBar from '../components/ArticleDownloadBar';
import { useLocalizedPath } from '../i18n/paths';
import { findArticle, loadArticleBody, guides, posts, articleLanguages } from '../content';

/**
 * Generic page for every article that comes from the content pack.
 * The body is fetched as its own chunk so a visit to one article never
 * downloads the other twenty.
 */
export default function Article({ type }) {
  const { t, i18n } = useTranslation('edb');
  const localize = useLocalizedPath();
  const { slug } = useParams();
  const meta = findArticle(type, slug, i18n.language);
  const languages = articleLanguages(type, slug);
  const bodyLang = languages.includes(i18n.language) ? i18n.language : 'en';
  const [html, setHtml] = useState(null);
  const [missing, setMissing] = useState(false);

  useEffect(() => {
    let live = true;
    setHtml(null);
    setMissing(false);
    loadArticleBody(type, slug, bodyLang)
      .then((body) => { if (!live) return; body ? setHtml(body) : setMissing(true); })
      .catch(() => { if (live) setMissing(true); });
    return () => { live = false; };
  }, [type, slug, bodyLang]);

  useEffect(() => {
    if (typeof window !== 'undefined') window.scrollTo(0, 0);
  }, [slug]);

  // Articles sharing this one's tag come first, then the rest in running order.
  const others = (type === 'guide' ? guides(i18n.language) : posts(i18n.language))
    .filter((a) => a.slug !== slug && a.card);
  const related = [
    ...others.filter((a) => meta?.tag && a.tag === meta.tag),
    ...others.filter((a) => !meta?.tag || a.tag !== meta.tag),
  ].slice(0, 3);

  const title = meta?.title || 'Article';
  const description = meta?.description || '';

  return (
    <BlogLayout
      languages={languages}
      title={title}
      seoTitle={meta?.seoTitle}
      description={description}
      readTime={meta?.readTime || null}
      section={type === 'guide' ? 'guides' : 'blog'}
      tag={meta?.tag}
      jsonLd={meta ? {
        '@context': 'https://schema.org',
        '@type': 'Article',
        headline: title,
        description,
        image: meta.image ? `https://externaldisplayiphone.com${meta.image}` : undefined,
        author: { '@type': 'Organization', name: 'XeOS' },
        publisher: { '@type': 'Organization', name: 'XeOS: External Display Browser' },
        mainEntityOfPage: `https://externaldisplayiphone.com${meta.href}`,
      } : null}
    >
      {html ? (
        <ArticleBody html={html} />
      ) : missing ? (
        <p className="text-slate-600 dark:text-slate-300">
          {t('article.notFound')}{' '}
          <a className="text-sky-600 dark:text-sky-400 hover:underline" href={localize(type === 'guide' ? '/guides' : '/blog')}>
            {type === 'guide' ? t('articleChrome.allGuides') : t('articleChrome.allArticles')}
          </a>.
        </p>
      ) : (
        <div className="space-y-3 animate-pulse" aria-hidden="true">
          {[90, 100, 80, 95, 60].map((w, i) => (
            <div key={i} className="h-4 rounded bg-slate-200 dark:bg-slate-700" style={{ width: `${w}%` }} />
          ))}
        </div>
      )}

      {related.length > 0 && (
        <section className="related-section mt-14 pt-10 border-t">
          <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-5">
            {type === 'guide' ? t('article.moreGuides') : t('article.moreFromBlog')}
          </h2>
          <div className="editorial-grid editorial-grid-related grid sm:grid-cols-3 gap-4">
            {related.map((a) => <ArticleCard key={a.slug} article={a} compact />)}
          </div>
        </section>
      )}

      <ArticleDownloadBar />
    </BlogLayout>
  );
}
